const ptaxRows = $items('Fetch PTAX Period', 0, 0)[0]?.json?.value || [];
const selicRows = $items('Fetch Selic Expectations', 0, 0)[0]?.json?.value || [];
const ipcaRows = $items('Fetch IPCA Expectations', 0, 0)[0]?.json?.value || [];
const cambioRows = $items('Fetch Cambio Expectations', 0, 0)[0]?.json?.value || [];

const staticData = $getWorkflowStaticData('global');
staticData.lastHash = staticData.lastHash || '';

const num = value => Number(value || 0);
const byDateDesc = (a, b) => String(b.Data || '').localeCompare(String(a.Data || ''));
const fmtPct = value => `${value >= 0 ? '+' : ''}${value.toFixed(2)}%`;
const fmtPp = value => `${value >= 0 ? '+' : ''}${value.toFixed(2)} pp`;
const fmtNum = value => Number(value || 0).toFixed(4);

const ptaxClosings = ptaxRows
  .filter(row => String(row.tipoBoletim || '').toLowerCase() === 'fechamento')
  .sort((a, b) => String(a.dataHoraCotacao || '').localeCompare(String(b.dataHoraCotacao || '')));

if (ptaxClosings.length < 2 || selicRows.length < 2 || ipcaRows.length < 2 || cambioRows.length < 2) {
  return [];
}

const ptaxLast = ptaxClosings[ptaxClosings.length - 1];
const ptaxPrev = ptaxClosings[ptaxClosings.length - 2];
const ptaxLastClose = num(ptaxLast.cotacaoVenda);
const ptaxPrevClose = num(ptaxPrev.cotacaoVenda);
const ptaxPct = ptaxPrevClose ? ((ptaxLastClose - ptaxPrevClose) / ptaxPrevClose) * 100 : 0;

const pickLatestPair = rows => {
  const sorted = [...rows].sort(byDateDesc);
  return [sorted[0], sorted.find(row => String(row.Data) !== String(sorted[0].Data)) || sorted[1]];
};

const [selicLast, selicPrev] = pickLatestPair(selicRows);
const [ipcaLast, ipcaPrev] = pickLatestPair(ipcaRows);
const [cambioLast, cambioPrev] = pickLatestPair(cambioRows);
if (!selicLast || !selicPrev || !ipcaLast || !ipcaPrev || !cambioLast || !cambioPrev) {
  return [];
}

const selicDelta = num(selicLast.Mediana) - num(selicPrev.Mediana);
const ipcaDelta = num(ipcaLast.Mediana) - num(ipcaPrev.Mediana);
const cambioDelta = num(cambioLast.Mediana) - num(cambioPrev.Mediana);

let pressureScore = 0;
let reliefScore = 0;
const reasons = [];

if (ptaxPct >= 0.35) {
  pressureScore += 34;
  reasons.push(`PTAX USD ${fmtPct(ptaxPct)}`);
} else if (ptaxPct <= -0.35) {
  reliefScore += 30;
  reasons.push(`PTAX USD ${fmtPct(ptaxPct)}`);
}

if (selicDelta >= 0.05) {
  pressureScore += 24;
  reasons.push(`Selic ${fmtPp(selicDelta)}`);
} else if (selicDelta <= -0.05) {
  reliefScore += 22;
  reasons.push(`Selic ${fmtPp(selicDelta)}`);
}

if (ipcaDelta >= 0.05) {
  pressureScore += 24;
  reasons.push(`IPCA ${fmtPp(ipcaDelta)}`);
} else if (ipcaDelta <= -0.05) {
  reliefScore += 22;
  reasons.push(`IPCA ${fmtPp(ipcaDelta)}`);
}

if (cambioDelta >= 0.03) {
  pressureScore += 18;
  reasons.push(`Cambio esp. ${fmtNum(cambioDelta)}`);
} else if (cambioDelta <= -0.03) {
  reliefScore += 16;
  reasons.push(`Cambio esp. ${fmtNum(cambioDelta)}`);
}

let regime = 'NEUTRAL';
let score = 0;
let tendency = 'sem leitura material no BCB direto';
let conviction = 'baixa';
let winRead = 'Sem acao. Aguardar mudanca material em PTAX ou expectativas.';
let dollarRead = 'Sem acao. Aguardar pressao ou alivio mais claro no BCB.';
let usRead = 'Global continua como confirmacao externa, mas este workflow e domestico.';
let reason = reasons.join('; ') || 'Sem mudanca material.';

if (pressureScore >= reliefScore && pressureScore >= 45) {
  regime = pressureScore >= 70 ? 'VERMELHO' : 'LARANJA';
  score = Math.min(140, pressureScore);
  tendency = 'vies de baixa para WIN';
  conviction = score >= 70 ? 'alta' : 'media-alta';
  winRead = 'WIN tende a sofrer se DI e dolar confirmarem alta e o indice perder VWAP.';
  dollarRead = 'Dolar local tende a ficar firme se PTAX e expectativas continuarem piorando.';
} else if (reliefScore > pressureScore && reliefScore >= 40) {
  regime = reliefScore >= 65 ? 'VERDE_FORTE' : 'ALIVIO';
  score = Math.min(140, reliefScore);
  tendency = 'vies de alta para WIN';
  conviction = score >= 65 ? 'alta' : 'media';
  winRead = 'WIN pode ganhar folego se DI aliviar, dolar ceder e o indice sustentar VWAP.';
  dollarRead = 'Dolar local tende a aliviar se PTAX e expectativas continuarem cedendo.';
}

if (score < 45) {
  return [];
}

const quoteLines = [
  `PTAX USD: ${ptaxLastClose.toFixed(4)} (${fmtPct(ptaxPct)})`,
  `Selic ${selicLast.DataReferencia}: ${num(selicLast.Mediana).toFixed(2)} (${fmtPp(selicDelta)})`,
  `IPCA ${ipcaLast.DataReferencia}: ${num(ipcaLast.Mediana).toFixed(2)} (${fmtPp(ipcaDelta)})`,
  `Cambio ${cambioLast.DataReferencia}: ${num(cambioLast.Mediana).toFixed(4)} (${fmtNum(cambioDelta)})`
].join('\n');

const hash = `${regime}|${score}|${quoteLines}`;
if (staticData.lastHash === hash) {
  return [];
}
staticData.lastHash = hash;

const discordText = `**BCB DIRECT | ${regime}**\n\n**Tendencia:** ${tendency}\n**Conviccao:** ${conviction}\n\n**WIN:** ${winRead}\n**Dolar:** ${dollarRead}\n**Nasdaq/ES:** ${usRead}\n\n**Leituras:**\n${quoteLines}\n\n**Motivo:** ${reason}\n**Fonte:** BCB PTAX + Expectativas`; 

return [{ json: {
  alert_type: 'brazil_local',
  regime: 'BR_LOCAL_BCB_DIRECT',
  level: regime,
  levelLabel: regime,
  score,
  title: 'BCB Direct Macro',
  tendency,
  conviction,
  win_read: winRead,
  dollar_read: dollarRead,
  us_read: usRead,
  reason,
  source: 'BCB PTAX + Expectativas',
  channels: ['telegram', 'discord', 'dashboard'],
  quoteLines,
  discordText,
  generatedAt: new Date().toISOString()
}}];
